const layers={interface:['01 / INTERFACE','Clear interactions. Responsive by design.'],backend:['02 / BACKEND','Protected APIs. Structured business logic.'],data:['03 / DATA','Connected records. Purposeful data models.']};document.querySelectorAll('[data-layer]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-layer]').forEach(node=>{node.classList.remove('active');node.setAttribute('aria-pressed','false')});button.classList.add('active');button.setAttribute('aria-pressed','true');const [title,description]=layers[button.dataset.layer];document.getElementById('layer-number').textContent=title;document.getElementById('layer-description').textContent=description}));document.querySelectorAll('[data-layer]').forEach(button=>button.setAttribute('aria-pressed',String(button.classList.contains('active'))));document.getElementById('copy-email').addEventListener('click',async()=>{const status=document.getElementById('copy-status');try{await navigator.clipboard.writeText('py.rajesh16@gmail.com');status.textContent='Email copied';setTimeout(()=>status.textContent='',3500)}catch{status.textContent='Email: py.rajesh16@gmail.com'}});document.getElementById('year').textContent=new Date().getFullYear();
